// ═══════════════════════════════════════════════════════════════════════════════
// Low-level helpers
// ═══════════════════════════════════════════════════════════════════════════════

function lbl(
  g: Gsel,
  x: number,
  y: number,
  text: string,
  opts: {
    size?: number;
    weight?: string;
    color?: string;
    anchor?: 'start' | 'middle' | 'end';
    font?: string;
  } = {}
): void {
  drawLabel(g as Sel, x, y, text, opts);
}

function arrowDown(g: Gsel, x: number, y1: number, y2: number, color = '#94a3b8'): void {
  drawArrow(g as Sel, x, y1, x, y2, { color });
}

function arrowH(g: Gsel, x1: number, x2: number, y: number, color = '#94a3b8'): void {
  drawArrow(g as Sel, x1, y, x2, y, { color });
}

function opCircle(g: Gsel, cx: number, cy: number, text: string, color: string): void {
  g.append('circle').attr('cx', cx).attr('cy', cy).attr('r', 14).attr('fill', '#fff').attr('stroke', color).attr('stroke-width', 2);
  lbl(g, cx, cy, text, { size: 12, weight: '700', color });
}

function roundBox(
  g: Gsel,
  cx: number,
  y: number,
  w: number,
  h: number,
  title: string,
  formula: string,
  fill: string,
  stroke: string
): number {
  const grp = g.append('g');
  grp
    .append('rect')
    .attr('x', cx - w / 2)
    .attr('y', y)
    .attr('width', w)
    .attr('height', h)
    .attr('rx', 6)
    .attr('fill', fill)
    .attr('stroke', stroke)
    .attr('stroke-width', 1.5);
  lbl(grp, cx, y + h / 2 - 6, title, { size: 11, weight: '600', color: 'var(--text)' });
  lbl(grp, cx, y + h / 2 + 8, formula, { size: 9, color: 'var(--text-muted)', font: 'monospace' });
  return y + h;
}

function drawParamSummary(g: Gsel, cx: number, y: number, dModel: number, seqLen: number, dFf: number): number {
  const grp = g.append('g').attr('transform', `translate(${cx - 220}, ${y})`);
  grp.append('rect').attr('width', 440).attr('height', 48).attr('rx', 6)
    .attr('fill', 'var(--surface)').attr('stroke', 'var(--border)').attr('stroke-width', 1);
  lbl(grp, 8, 14, 'Parameters →', { size: 8, weight: '700', color: 'var(--text-muted)' });

  const items = [
    { label: `d_model = ${dModel}`, dim: 'feature dim', color: '#4caf50' },
    { label: `seq_len = ${seqLen}`, dim: 'sequence dim', color: '#1976d2' },
    { label: `d_ff = ${dFf}`, dim: 'FFN width', color: '#7c3aed' },
  ];
  items.forEach((item, i) => {
    const px = 10 + i * 148;
    grp.append('rect').attr('x', px).attr('y', 22).attr('width', 140).attr('height', 18).attr('rx', 4)
      .attr('fill', hexWithAlpha(item.color, 0.08)).attr('stroke', item.color).attr('stroke-width', 1);
    lbl(grp, px + 6, 31, item.label, { size: 7, weight: '600', color: item.color, font: 'monospace', anchor: 'start' });
    lbl(grp, px + 6, 38, `→ ${item.dim}`, { size: 6, color: item.color, anchor: 'start' });
  });
  return y + 56;
}

function hexWithAlpha(hex: string, alpha: number): string {
  const v = hex.replace('#', '');
  const bigint = parseInt(v, 16);
  const r = (bigint >> 16) & 255;
  const g = (bigint >> 8) & 255;
  const b = bigint & 255;
  return `rgba(${r}, ${g}, ${b}, ${alpha})`;
}

// ═══════════════════════════════════════════════════════════════════════════════
// Matrix helpers
