function drawSeqMatrix(
  g: Gsel,
  x: number,
  y: number,
  label: string,
  sublabel: string,
  fill = COLORS.x.fill,
  stroke = COLORS.x.stroke
): number {
  drawMatrixBlock(g as Sel, x, y, {
    width: 120,
    height: 50,
    label,
    sublabel,
    fill,
    stroke,
    cols: 8,
    rows: 5,
    dimRight: 'D',
    dimTop: 'S',
  });
  return y + 50;
}

function drawWeightMatrix(
  g: Gsel,
  x: number,
  y: number,
  label: string,
  sublabel: string,
  fill = COLORS.weight.fill,
  stroke = COLORS.weight.stroke
): number {
  drawMatrixBlock(g as Sel, x, y, {
    width: 70,
    height: 50,
    label,
    sublabel,
    fill,
    stroke,
    cols: 5,
    rows: 5,
  });
  return y + 50;
}

function drawSmallVector(
  g: Gsel,
  x: number,
  y: number,
  label: string,
  sublabel: string,
  fill = COLORS.ffn.fill,
  stroke = COLORS.ffn.stroke
): number {
  drawMatrixBlock(g as Sel, x, y, {
    width: 100,
    height: 18,
    label,
    sublabel,
    fill,
    stroke,
    cols: 8,
    rows: 1,
  });
  return y + 18;
}

// ═══════════════════════════════════════════════════════════════════════════════
// Higher-level layout helpers
// ═══════════════════════════════════════════════════════════════════════════════

function stepBox(g: Gsel, cx: number, y: number, title: string, formula: string, fill: string, stroke: string): number {
  return roundBox(g, cx, y, 320, 42, title, formula, fill, stroke);
}

function drawNormBlock(g: Gsel, cx: number, y: number, className: string, stepId: number): { y: number; group: Gsel } {
  const grp = g.append('g').attr('class', `step-node ${className}`).attr('data-step', String(stepId));
  const by = stepBox(grp, cx, y, 'LayerNorm', 'x̂ = (x − μ)/(σ + ε)', COLORS.norm.fill, COLORS.norm.stroke);
  y = by + 14;
  drawSeqMatrix(grp, cx - 60, y, 'x̂', 'LN(x) [S, D]', COLORS.norm.fill, COLORS.norm.stroke);
  y += 62;
  return { y, group: grp };
}

function drawFFNHorizontal(g: Gsel, cx: number, y: number, className: string, stepId: number, inputLabel = 'x̂'): { y: number; group: Gsel } {
  const grp = g.append('g').attr('class', `step-node ${className}`).attr('data-step', String(stepId));

  // Step label
  const by = stepBox(grp, cx, y, 'FFN sub-layer', 'h = W_down(GELU(input W_up))', COLORS.ffn.fill, COLORS.ffn.stroke);
  y = by + 18;

  // Draw horizontal FFN pipeline centered around cx
  const rowY = y;
  const inputX = cx - 245;
  const wupX = cx - 135;
  const actX = cx - 45;
  const wdownX = cx + 45;
  const outX = cx + 155;

  drawSmallVector(grp, inputX, rowY, inputLabel, '[S, D]', COLORS.norm.fill, COLORS.norm.stroke);
  arrowH(grp, inputX + 100, wupX, rowY + 9);

  drawWeightMatrix(grp, wupX, rowY - 16, 'W_up', '[D, d_ff]', COLORS.weight.fill, COLORS.weight.stroke);
  lbl(grp, wupX + 35, rowY + 42, 'expand', { size: 8, color: COLORS.muted });
  arrowH(grp, wupX + 70, actX, rowY + 9);

  opCircle(grp, actX + 14, rowY + 9, 'σ', COLORS.ffn.stroke);
  lbl(grp, actX + 14, rowY + 34, 'GELU', { size: 8, color: COLORS.muted });
  arrowH(grp, actX + 28, wdownX, rowY + 9);

  drawWeightMatrix(grp, wdownX, rowY - 16, 'W_down', '[d_ff, D]', COLORS.weight.fill, COLORS.weight.stroke);
  lbl(grp, wdownX + 35, rowY + 42, 'project back', { size: 8, color: COLORS.muted });
  arrowH(grp, wdownX + 70, outX, rowY + 9);

  drawSmallVector(grp, outX, rowY, 'h', '[S, D]', COLORS.ffn.fill, COLORS.ffn.stroke);

  y = rowY + 58;
  return { y, group: grp };
}

function drawResidualAdd(
  g: Gsel,
  cx: number,
  y: number,
  className: string,
  stepId: number,
  leftLabel: string,
  rightLabel: string,
  outLabel: string,
  leftFill = COLORS.x.fill,
  leftStroke = COLORS.x.stroke,
  rightFill = COLORS.ffn.fill,
  rightStroke = COLORS.ffn.stroke
): { y: number; group: Gsel } {
  const grp = g.append('g').attr('class', `step-node ${className}`).attr('data-step', String(stepId));

  const by = stepBox(grp, cx, y, 'Residual addition', 'r = skip + sublayer', COLORS.add.fill, COLORS.add.stroke);
  y = by + 16;

  const leftX = cx - 130;
  const rightX = cx + 50;
  const addY = y + 70;   // below both matrices (matrix height = 50, gap = 20)
  const outY = y + 120;  // below plus circle (r=14, gap = 36)

  drawSeqMatrix(grp, leftX, y, leftLabel, 'skip [S, D]', leftFill, leftStroke);
  drawSeqMatrix(grp, rightX, y, rightLabel, 'sublayer [S, D]', rightFill, rightStroke);

  // Arrows into plus
  drawArrow(grp as Sel, leftX + 60, y + 50, cx, addY, { color: leftStroke });
  drawArrow(grp as Sel, rightX + 60, y + 50, cx, addY, { color: rightStroke });
  opCircle(grp, cx, addY, '+', COLORS.add.stroke);

  // Arrow down to output
  arrowDown(grp, cx, addY + 14, outY, COLORS.add.stroke);
  drawSeqMatrix(grp, cx - 60, outY, outLabel, '[S, D]', COLORS.out.fill, COLORS.out.stroke);

  y = outY + 62;
  return { y, group: grp };
}

function drawFinalNorm(g: Gsel, cx: number, y: number, className: string, stepId: number, inLabel = 'r', outLabel = 'out'): { y: number; group: Gsel } {
  const grp = g.append('g').attr('class', `step-node ${className}`).attr('data-step', String(stepId));
  const by = stepBox(grp, cx, y, 'LayerNorm after add', 'out = LN(r)', COLORS.norm.fill, COLORS.norm.stroke);
  y = by + 14;
  drawSeqMatrix(grp, cx - 60, y, inLabel, '[S, D]', COLORS.add.fill, COLORS.add.stroke);
  arrowDown(grp, cx, y + 62, y + 82);
  drawSeqMatrix(grp, cx - 60, y + 84, outLabel, '[S, D]', COLORS.out.fill, COLORS.out.stroke);
  y += 146;
  return { y, group: grp };
}

// ═══════════════════════════════════════════════════════════════════════════════
// Variant renderers
// ═══════════════════════════════════════════════════════════════════════════════

function renderPreNorm(_g: Gsel, cx: number, y: number): RenderResult {
  const steps: ResidualStep[] = [];

  // 1. Input
  steps.push({ ...BASE_STEPS.input, id: 1 });
  const inputGrp = _g.append('g').attr('class', `step-node ${STEP_GROUPS.input}`).attr('data-step', '1');
  drawSeqMatrix(inputGrp, cx - 60, y, 'x', '[S, D]', COLORS.x.fill, COLORS.x.stroke);
  y += 72;

  // 2. Norm
  steps.push({ ...BASE_STEPS.norm, id: 2 });
  arrowDown(_g, cx, y - 16, y, COLORS.norm.stroke);
  const normRes = drawNormBlock(_g, cx, y, STEP_GROUPS.norm, 2);
  y = normRes.y;

  // 3. FFN
  steps.push({ ...BASE_STEPS.ffnUp, id: 3 });
  arrowDown(_g, cx, y - 16, y, COLORS.ffn.stroke);
  const ffnRes = drawFFNHorizontal(_g, cx, y, STEP_GROUPS.ffnUp, 3);
  y = ffnRes.y;

  // 4. Add
  steps.push({ ...BASE_STEPS.add, id: 4 });
  arrowDown(_g, cx, y - 16, y, COLORS.add.stroke);
  const addRes = drawResidualAdd(_g, cx, y, STEP_GROUPS.add, 4, 'x', 'h', 'out');
  y = addRes.y;

  // 5. Output
  steps.push({ ...BASE_STEPS.output, id: 5 });

  return { steps, y };
}

function renderPostNorm(_g: Gsel, cx: number, y: number): RenderResult {
  const steps: ResidualStep[] = [];

  // 1. Input
  steps.push({ ...BASE_STEPS.input, id: 1 });
  const inputGrp = _g.append('g').attr('class', `step-node ${STEP_GROUPS.input}`).attr('data-step', '1');
  drawSeqMatrix(inputGrp, cx - 60, y, 'x', '[S, D]', COLORS.x.fill, COLORS.x.stroke);
  y += 72;

  // 2. FFN on raw input
  steps.push({
    ...BASE_STEPS.ffnUp,
    id: 2,
    label: 'FFN sub-layer on x',
    shortLabel: 'FFN(x)',
    formula: 'h = FFN(x)',
    explanation: 'In Post-Norm the sub-layer is applied directly to the unnormalized input.',
  });
  arrowDown(_g, cx, y - 16, y, COLORS.ffn.stroke);
  const ffnRes = drawFFNHorizontal(_g, cx, y, STEP_GROUPS.ffnUp, 2, 'x');
  y = ffnRes.y;

  // 3. Add
  steps.push({ ...BASE_STEPS.add, id: 3 });
  arrowDown(_g, cx, y - 16, y, COLORS.add.stroke);
  const addRes = drawResidualAdd(_g, cx, y, STEP_GROUPS.add, 3, 'x', 'h', 'r');
  y = addRes.y;

  // 4. Norm after add
  steps.push({
    ...BASE_STEPS.norm,
    id: 4,
    label: 'LayerNorm after residual',
    shortLabel: 'Post-Add LN',
    formula: 'out = LN(x + h)',
    explanation:
      'Post-Norm places the normalization after the residual addition. This was used in the original Transformer ' +
      'but can make very deep networks harder to train because gradients must pass through the normalization.',
  });
  arrowDown(_g, cx, y - 16, y, COLORS.norm.stroke);
  const normRes = drawFinalNorm(_g, cx, y, STEP_GROUPS.norm, 4, 'r', 'out');
  y = normRes.y;

  // 5. Output
  steps.push({ ...BASE_STEPS.output, id: 5 });

  return { steps, y };
}

function renderDeepNorm(_g: Gsel, cx: number, y: number): RenderResult {
  const steps: ResidualStep[] = [];
  const alpha = Math.pow(2 * 32, 0.25).toFixed(2); // illustrative depth N=32

  // 1. Input
  steps.push({ ...BASE_STEPS.input, id: 1 });
  const inputGrp = _g.append('g').attr('class', `step-node ${STEP_GROUPS.input}`).attr('data-step', '1');
  drawSeqMatrix(inputGrp, cx - 60, y, 'x', '[S, D]', COLORS.x.fill, COLORS.x.stroke);
  y += 72;

  // 2. Scale skip path
  steps.push({
    id: 2,
    label: 'Scale skip by α',
    shortLabel: 'Scale',
    formula: 'α·x, α = (2N)^(1/4)',
    explanation:
      'DeepNorm magnifies the residual branch by a constant α that grows with model depth N. ' +
      'This keeps activation magnitudes stable at initialization in very deep networks.',
    code: { title: 'DeepNorm scaling', lines: [`alpha = (2 * N) ** 0.25  # ≈ ${alpha}`, 'scaled_x = alpha * x'] },
    svgGroup: STEP_GROUPS.scale,
    color: '#d97706',
    fill: '#fef3c7',
  });
  arrowDown(_g, cx, y - 16, y, '#d97706');
  const scaleGrp = _g.append('g').attr('class', `step-node ${STEP_GROUPS.scale}`).attr('data-step', '2');
  drawSeqMatrix(scaleGrp, cx - 60, y, 'α·x', 'scaled skip [S, D]', '#fef3c7', '#d97706');
  lbl(scaleGrp, cx + 80, y + 25, `α ≈ ${alpha}`, { size: 10, color: '#d97706', anchor: 'start' });
  y += 72;

  // 3. FFN on raw input
  steps.push({ ...BASE_STEPS.ffnUp, id: 3, label: 'FFN sub-layer on x', shortLabel: 'FFN(x)', formula: 'h = FFN(x)' });
  arrowDown(_g, cx, y - 16, y, COLORS.ffn.stroke);
  const ffnRes = drawFFNHorizontal(_g, cx, y, STEP_GROUPS.ffnUp, 3, 'x');
  y = ffnRes.y;

  // 4. Add
  steps.push({ ...BASE_STEPS.add, id: 4 });
  arrowDown(_g, cx, y - 16, y, COLORS.add.stroke);
  const addRes = drawResidualAdd(_g, cx, y, STEP_GROUPS.add, 4, 'α·x', 'h', 'r', '#fef3c7', '#d97706');
  y = addRes.y;

  // 5. Norm
  steps.push({
    ...BASE_STEPS.norm,
    id: 5,
    label: 'LayerNorm after scaled residual',
    shortLabel: 'DeepNorm',
    formula: 'out = LN(α·x + h)',
    explanation:
      'The scaled skip path dominates the residual sum, so DeepNorm networks can be trained hundreds of layers deep ' +
      'without activation explosion.',
  });
  arrowDown(_g, cx, y - 16, y, COLORS.norm.stroke);
  const normRes = drawFinalNorm(_g, cx, y, STEP_GROUPS.norm, 5, 'r', 'out');
  y = normRes.y;

  // 6. Output
  steps.push({ ...BASE_STEPS.output, id: 6 });

  return { steps, y };
}

function renderSandwich(_g: Gsel, cx: number, y: number): RenderResult {
  const steps: ResidualStep[] = [];

  // 1. Input
  steps.push({ ...BASE_STEPS.input, id: 1 });
  const inputGrp = _g.append('g').attr('class', `step-node ${STEP_GROUPS.input}`).attr('data-step', '1');
  drawSeqMatrix(inputGrp, cx - 60, y, 'x', '[S, D]', COLORS.x.fill, COLORS.x.stroke);
  y += 72;

  // 2. Inner Norm
  steps.push({ ...BASE_STEPS.norm, id: 2, label: 'Inner LayerNorm', shortLabel: 'Inner LN' });
  arrowDown(_g, cx, y - 16, y, COLORS.norm.stroke);
  const norm1 = drawNormBlock(_g, cx, y, STEP_GROUPS.norm, 2);
  y = norm1.y;

  // 3. FFN
  steps.push({ ...BASE_STEPS.ffnUp, id: 3, label: 'FFN sub-layer', shortLabel: 'FFN' });
  arrowDown(_g, cx, y - 16, y, COLORS.ffn.stroke);
  const ffnRes = drawFFNHorizontal(_g, cx, y, STEP_GROUPS.ffnUp, 3, 'x̂');
  y = ffnRes.y;

  // 4. Inner Norm after FFN
  steps.push({
    ...BASE_STEPS.norm,
    id: 4,
    label: 'Inner LayerNorm after FFN',
    shortLabel: 'Post-FFN LN',
    formula: 'h = LN(FFN(LN(x)))',
    explanation: 'Sandwich Norm adds an extra normalization after the sub-layer, before adding the skip path.',
  });
  arrowDown(_g, cx, y - 16, y, COLORS.norm.stroke);
  const norm2 = drawNormBlock(_g, cx, y, STEP_GROUPS.norm, 4);
  y = norm2.y;

  // 5. Add
  steps.push({ ...BASE_STEPS.add, id: 5 });
  arrowDown(_g, cx, y - 16, y, COLORS.add.stroke);
  const addRes = drawResidualAdd(_g, cx, y, STEP_GROUPS.add, 5, 'x', 'h', 'r');
  y = addRes.y;

  // 6. Outer Norm
  steps.push({
    ...BASE_STEPS.norm,
    id: 6,
    label: 'Outer LayerNorm',
    shortLabel: 'Outer LN',
    formula: 'out = LN(x + LN(FFN(LN(x))))',
    explanation:
      'A final normalization wraps the whole block. The extra norms improve training stability at the cost of more computation.',
  });
  arrowDown(_g, cx, y - 16, y, COLORS.norm.stroke);
  const norm3 = drawFinalNorm(_g, cx, y, STEP_GROUPS.norm, 6, 'r', 'out');
  y = norm3.y;

  // 7. Output
  steps.push({ ...BASE_STEPS.output, id: 7 });

  return { steps, y };
}

function renderParallel(_g: Gsel, cx: number, y: number): RenderResult {
  const steps: ResidualStep[] = [];

  // 1. Input
  steps.push({ ...BASE_STEPS.input, id: 1 });
  const inputGrp = _g.append('g').attr('class', `step-node ${STEP_GROUPS.input}`).attr('data-step', '1');
  drawSeqMatrix(inputGrp, cx - 60, y, 'x', '[S, D]', COLORS.x.fill, COLORS.x.stroke);
  y += 72;

  // 2. Shared Norm
  steps.push({ ...BASE_STEPS.norm, id: 2, label: 'Shared LayerNorm', shortLabel: 'Shared LN' });
  arrowDown(_g, cx, y - 16, y, COLORS.norm.stroke);
  const normRes = drawNormBlock(_g, cx, y, STEP_GROUPS.norm, 2);
  y = normRes.y;

  // 3. Branches label
  steps.push({
    id: 3,
    label: 'Attention + FFN in parallel',
    shortLabel: 'Parallel branches',
    formula: 'a = Attn(x̂), f = FFN(x̂)',
    explanation:
      'PaLM-style parallel block runs attention and feed-forward on the same normalized input simultaneously, ' +
      'rather than stacking them sequentially. This reduces effective depth and speeds up training.',
    code: {
      title: 'Parallel branches',
      lines: [
        'x_hat = ln(x)',
        'a = attention(x_hat)  # [B, S, D]',
        'f = ffn(x_hat)        # [B, S, D]',
      ],
    },
    svgGroup: STEP_GROUPS.ffnUp,
    color: COLORS.ffn.stroke,
    fill: COLORS.ffn.fill,
  });
  arrowDown(_g, cx, y - 16, y, COLORS.ffn.stroke);

  const branchGrp = _g.append('g').attr('class', `step-node ${STEP_GROUPS.ffnUp}`).attr('data-step', '3');
  const by = stepBox(branchGrp, cx, y, 'Parallel branches', 'a = Attn(x̂), f = FFN(x̂)', COLORS.ffn.fill, COLORS.ffn.stroke);
  y = by + 18;

  // Shared normalized input above branches
  const sharedY = y;
  drawSmallVector(branchGrp, cx - 50, sharedY, 'x̂', '[S, D]', COLORS.norm.fill, COLORS.norm.stroke);
  arrowDown(branchGrp, cx, sharedY + 20, sharedY + 40, COLORS.norm.stroke);
  opCircle(branchGrp, cx, sharedY + 54, '×1', COLORS.norm.stroke);
  lbl(branchGrp, cx + 20, sharedY + 54, 'shared LN', { size: 8, color: COLORS.muted, anchor: 'start' });
  y = sharedY + 70;

  // Attention branch (left)
  const attnY = y;
  drawSmallVector(branchGrp, cx - 230, attnY, 'x̂', '[S, D]', COLORS.norm.fill, COLORS.norm.stroke);
  arrowH(branchGrp, cx - 130, cx - 100, attnY + 9, COLORS.attn.stroke);
  drawWeightMatrix(branchGrp, cx - 100, attnY - 16, 'W_attn', '[D, D]', COLORS.attn.fill, COLORS.attn.stroke);
  arrowH(branchGrp, cx - 30, cx + 10, attnY + 9, COLORS.attn.stroke);
  drawSmallVector(branchGrp, cx + 10, attnY, 'a', '[S, D]', COLORS.attn.fill, COLORS.attn.stroke);
  lbl(branchGrp, cx - 95, attnY + 44, 'Attention branch', { size: 8, color: COLORS.attn.stroke, anchor: 'start' });

  // FFN branch (right)
  const ffnY = attnY + 60;
  drawSmallVector(branchGrp, cx - 230, ffnY, 'x̂', '[S, D]', COLORS.norm.fill, COLORS.norm.stroke);
  arrowH(branchGrp, cx - 130, cx - 100, ffnY + 9, COLORS.ffn.stroke);
  drawWeightMatrix(branchGrp, cx - 100, ffnY - 16, 'W_up', '[D, d_ff]', COLORS.weight.fill, COLORS.weight.stroke);
  arrowH(branchGrp, cx - 30, cx + 10, ffnY + 9, COLORS.ffn.stroke);
  drawSmallVector(branchGrp, cx + 10, ffnY, 'f', '[S, D]', COLORS.ffn.fill, COLORS.ffn.stroke);
  lbl(branchGrp, cx - 95, ffnY + 44, 'FFN branch', { size: 8, color: COLORS.ffn.stroke, anchor: 'start' });

  y = ffnY + 62;

  // 4. Triple add
  steps.push({
    id: 4,
    label: 'Residual addition (three-way)',
    shortLabel: 'Triple add',
    formula: 'out = x + a + f',
    explanation:
      'Both branch outputs are added to the original skip path. The triple sum is the output of the parallel block.',
    code: { title: 'Parallel residual add', lines: ['out = x + a + f'] },
    svgGroup: STEP_GROUPS.add,
    color: COLORS.add.stroke,
    fill: COLORS.add.fill,
  });
  arrowDown(_g, cx, y - 16, y, COLORS.add.stroke);

  const addGrp = _g.append('g').attr('class', `step-node ${STEP_GROUPS.add}`).attr('data-step', '4');
  const addBy = stepBox(addGrp, cx, y, 'Residual addition', 'out = x + a + f', COLORS.add.fill, COLORS.add.stroke);
  y = addBy + 16;

  const addCy = y + 70;   // below the three matrices
  const outY = y + 120;   // below the plus circle
  drawSeqMatrix(addGrp, cx - 220, y, 'x', 'skip [S, D]', COLORS.x.fill, COLORS.x.stroke);
  drawSeqMatrix(addGrp, cx - 60, y, 'a', 'attn [S, D]', COLORS.attn.fill, COLORS.attn.stroke);
  drawSeqMatrix(addGrp, cx + 100, y, 'f', 'ffn [S, D]', COLORS.ffn.fill, COLORS.ffn.stroke);

  // Arrows converge to central plus
  drawArrow(addGrp as Sel, cx - 160, y + 50, cx, addCy, { color: COLORS.x.stroke });
  drawArrow(addGrp as Sel, cx, y + 50, cx, addCy, { color: COLORS.attn.stroke });
  drawArrow(addGrp as Sel, cx + 160, y + 50, cx, addCy, { color: COLORS.ffn.stroke });
  opCircle(addGrp, cx, addCy, '+', COLORS.add.stroke);

  arrowDown(addGrp, cx, addCy + 14, outY, COLORS.add.stroke);
  drawSeqMatrix(addGrp, cx - 60, outY, 'out', '[S, D]', COLORS.out.fill, COLORS.out.stroke);
  y = outY + 62;

  // 5. Output
  steps.push({ ...BASE_STEPS.output, id: 5 });

  return { steps, y };
}

// ═══════════════════════════════════════════════════════════════════════════════
// Main entry
// ═══════════════════════════════════════════════════════════════════════════════

export function renderResidualConnectionDetailed(
  g: Gsel,
  params: Record<string, number | string>,
  _meta: ComponentDef,
  _graph: ComputationGraph
): { width: number; height: number; steps: ResidualStep[] } {
  const variant = String(params.variant || 'pre_norm');
  const dModel = Number(params.d_model) || 512;
  const seqLen = Number(params.seq_len) || 128;
  const dFf = Number(params.d_ff) || 2048;

  let y = 28;

  // Title
  lbl(g, CX, y, 'Residual Connection', { size: 15, weight: '700', color: COLORS.text });
  y += 18;
  lbl(g, CX, y, `variant = ${variant.replace(/_/g, '-')}`, { size: 10, color: COLORS.muted });
  y += 22;

  // Param summary
  y = drawParamSummary(g, CX, y, dModel, seqLen, dFf);
  y += 16;

  let result: RenderResult;
  switch (variant) {
    case 'post_norm':
      result = renderPostNorm(g, CX, y);
      break;
    case 'deepnorm':
      result = renderDeepNorm(g, CX, y);
      break;
    case 'sandwich':
      result = renderSandwich(g, CX, y);
      break;
    case 'parallel':
      result = renderParallel(g, CX, y);
      break;
    case 'pre_norm':
    default:
      result = renderPreNorm(g, CX, y);
      break;
  }

  // FLOP / param summary at bottom
  const flopsPerToken = 2 * dModel * dFf + 2 * dModel * dFf; // rough FFN flops
  const paramCount = 2 * dModel * dFf + 2 * dModel; // W_up, W_down, LN gamma/beta
  const summaryGrp = g.append('g');
  lbl(summaryGrp, CX, result.y + 14, `≈ ${(paramCount / 1e6).toFixed(2)}M params · ~${(flopsPerToken / 1e6).toFixed(2)} MFLOP/token`, {
    size: 9,
    color: COLORS.muted,
  });
  result.y += 32;

  return { width: W, height: result.y + 16, steps: result.steps };
}
